// ServerInterface represents all server handlers.
type ServerInterface interface {
	// ListListingJobs One page of preparation jobs
	// (GET /api/listing/jobs)
	ListListingJobs(w http.ResponseWriter, r *http.Request)
	// GetListingRun One preparation job in the active workspace
	// (GET /api/listing/jobs/{id})
	GetListingRun(w http.ResponseWriter, r *http.Request, id string)
	// PostListingSubmit Freeze stored rows or drafts and enqueue listing.submit.batch. The body shape selects the path: row_ids is a stored-row batch send, store_id or items is a Draft send, anything else is a tag check. A stored-row send requires the exact server revisions captured by the click. A tag check needs no principal; a batch or Draft send requires the submit role. It does not dial Ozon.
	// (POST /api/listing/submit)
	PostListingSubmit(w http.ResponseWriter, r *http.Request)
}

